    categorias: c.json.categorias_interesse || [],
    uf_interesse: c.json.uf_interesse || ['BR'],
    valor_minimo: c.json.valor_minimo || 10000,
    valor_maximo: c.json.valor_maximo || 5000000,
    margem_minima: c.json.margem_minima_percentual || 15,
    desde: duasHorasAtras,
