const resp = $input.item.json;
const config = $('⚙️ Prep Busca por Cliente').item.json;

const text = (resp.content || []).map(b => b.type === 'text' ? b.text : '').join('\n');
let parsed;
try {
  const match = text.replace(/```json|```/g,'').trim().match(/\{[\s\S]*\}/);
  parsed = match ? JSON.parse(match[0]) : { licitacoes: [] };
} catch(e) { parsed = { licitacoes: [] }; }

// Filtra por score e valor
const filtradas = (parsed.licitacoes || [])
  .filter(l => l.score_relevancia >= 6 && l.valor_estimado >= config.valor_minimo)
  .sort((a,b) => b.score_relevancia - a.score_relevancia)
  .slice(0, 10);

return filtradas.map(l => ({
  json: {
    ...config,
    licitacao: l,
    ja_processada: false
  }
}));

const existe = $input.item.json;
const dados = $('⚙️ Parse + Filtrar Licitações').item.json;
// Se retornou algum registro, já foi processada
if (existe && existe.id) {
  return [{ json: { ...dados, ja_processada: true } }];
}
return [{ json: { ...dados, ja_processada: false } }];

