const resp = $input.item.json;
const dados = $('⚙️ Parse Resumo').item.json;

const text = (resp.content || []).map(b => b.type === 'text' ? b.text : '').join('\n');
let fornecedores;
try {
  const match = text.replace(/```json|```/g,'').trim().match(/\{[\s\S]*\}/);
  fornecedores = match ? JSON.parse(match[0]) : { fornecedores: [] };
} catch(e) { fornecedores = { fornecedores: [], margem_estimada_percentual: 0 }; }

return [{ json: { ...dados, analise_fornecedores: fornecedores } }];

const d = $input.item.json;
const lit = d.licitacao;
const res = d.resumo_edital;
const forn = d.analise_fornecedores;

const top3forn = (forn.fornecedores || []).slice(0, 3)
  .map((f, i) => `${i+1}. *${f.nome_empresa}* — R$${f.preco_estimado_unitario?.toFixed(2) || 'N/D'}/un | ${f.prazo_entrega_dias}d | ${f.diferenciais}`)
  .join('\n');

const pontos = (res.pontos_atencao || []).map(p => `⚠️ ${p}`).join('\n');
const docs = (res.documentos_habilitacao || []).slice(0, 5).map(d => `📄 ${d}`).join('\n');

const viabilidadeEmoji = res.viabilidade_score >= 8 ? '🟢' : res.viabilidade_score >= 6 ? '🟡' : '🔴';

const msg = `⚖️ *NOVA LICITAÇÃO IDENTIFICADA*

*${lit.orgao}*
📋 Edital: ${lit.numero_edital}
🏛️ Plataforma: ${lit.plataforma} | ${lit.uf}

📦 *O que o governo quer:*
${res.resumo_executivo}

💰 *Valores:*
• Estimado: R$${lit.valor_estimado?.toLocaleString('pt-BR') || 'N/D'}
• Custo estimado: R$${forn.custo_total_estimado?.toLocaleString('pt-BR') || 'N/D'}
• Lucro estimado: R$${forn.lucro_estimado?.toLocaleString('pt-BR') || 'N/D'}
• Margem: ${forn.margem_estimada_percentual || 0}%

${viabilidadeEmoji} *Viabilidade: ${res.viabilidade_score}/10*
${res.justificativa_viabilidade}

📅 *Prazos:*
• Abertura: ${lit.data_abertura}
• Encerramento: ${lit.data_encerramento}
• Entrega: ${res.prazo_entrega_dias} dias

📋 *Documentos necessários:*
${docs}

${pontos ? `⚠️ *Pontos de Atenção:*\n${pontos}` : ''}

🏭 *Top 3 Fornecedores:*
${top3forn}

🔗 ${lit.link_edital}

Responda *SIM* para confirmar participação ou *NÃO* para ignorar.`;

return [{ json: { ...d, mensagem_whatsapp: msg } }];

const body = $input.item.json.body || $input.item.json;
const data = body.data || {};
const msg = (data.message?.conversation || data.message?.extendedTextMessage?.text || '').trim().toUpperCase();
const from = data.key?.remoteJid?.replace('@s.whatsapp.net','') || '';
const pushName = data.pushName || '';

return [{ json: {
  from, pushName, mensagem: msg,
  eh_confirmacao: msg === 'SIM' || msg.includes('SIM'),
  eh_rejeicao: msg === 'NÃO' || msg === 'NAO' || msg.includes('NÃO'),
  eh_lance: msg.startsWith('LANCE') || msg.startsWith('PARTICIPAR'),
  eh_limite: msg.startsWith('LIMITE') || msg.startsWith('MAX'),
  raw_msg: (data.message?.conversation || data.message?.extendedTextMessage?.text || '').trim()
} }];

