const resp = $input.item.json;
const licitacao = $('🗄️ Buscar Licitações Ativas').item.json;

const text = (resp.content || []).map(b => b.type === 'text' ? b.text : '').join('\n');
let analise;
try {
  const match = text.replace(/```json|```/g,'').trim().match(/\{[\s\S]*\}/);
  analise = match ? JSON.parse(match[0]) : { deve_dar_lance: false, sessao_ativa: false };
} catch(e) { analise = { deve_dar_lance: false, sessao_ativa: false }; }

// Verifica se lance sugerido está dentro do limite máximo
const dentroDolimite = analise.valor_lance_sugerido <= (licitacao.lance_maximo || 0);
const deveAvisar = analise.deve_dar_lance && dentroDolimite && analise.sessao_ativa;
const atingiuLimite = analise.valor_lance_sugerido > (licitacao.lance_maximo || 0);

return [{ json: {
  ...licitacao,
  analise_lance: analise,
  deve_avisar: deveAvisar,
  atingiu_limite: atingiuLimite
} }];

const d = $input.item.json;
const a = d.analise_lance;

let msg;
if (d.atingiu_limite) {
  msg = `🛑 *LIMITE ATINGIDO — ${d.numero_edital}*

O lance necessário agora seria R$${a.valor_lance_sugerido?.toLocaleString('pt-BR')}, mas seu limite máximo é R$${d.lance_maximo?.toLocaleString('pt-BR')}.

Estou saindo desta licitação automaticamente.

❌ Margem não comporta mais lances.`;
} else if (a.fase === 'iminente') {
  msg = `⚡ *LANCE URGENTE — ${d.numero_edital}*

⏰ ${a.minutos_para_encerrar} minutos para encerrar!

🏆 Lance vencedor atual: R$${a.lance_vencedor_atual?.toLocaleString('pt-BR')}
💡 Lance sugerido: *R$${a.valor_lance_sugerido?.toLocaleString('pt-BR')}*

📊 ${a.justificativa}

*Acesse agora a plataforma e dê este lance!*
🔗 ${d.link_edital}`;
} else {
  msg = `🎯 *OPORTUNIDADE DE LANCE — ${d.numero_edital}*

🏆 Lance vencedor atual: R$${a.lance_vencedor_atual?.toLocaleString('pt-BR')}
👥 Participantes: ${a.num_participantes}

💡 *Lance sugerido: R$${a.valor_lance_sugerido?.toLocaleString('pt-BR')}*

📊 ${a.justificativa}

*Acesse a plataforma para dar o lance:*
🔗 ${d.link_edital}`;
}

return [{ json: { ...d, mensagem_lance: msg } }];

